def longest_ordered_balanced_binary_substring(s):
    best=zeros=ones=0
    for char in s:
        if char=='0':
            if ones:zeros=0;ones=0
            zeros+=1
        else:
            ones+=1;best=max(best,2*min(zeros,ones))
    return best

